<script setup lang="ts">
import { ref } from "vue";
import { onLoad, onPullDownRefresh } from "@dcloudio/uni-app";
import WareState from "@/shared/components/WareState.vue";
import WarePhoneLink from "@/shared/components/WarePhoneLink.vue";
import { baseStocktakingApi, type StocktakingItem } from "../../api/base-stocktaking.api";
const baseId=ref(0),supplierId=ref(0),date=ref(""),supplier=ref<{name:string;phone:string}>(),items=ref<StocktakingItem[]>([]),loading=ref(true),error=ref("");
function specification(value:string){if(!value)return"";try{const v=JSON.parse(value);if(Array.isArray(v))return v.map(x=>typeof x==='string'?x:(x.value||x.name||'')).filter(Boolean).join(' ');if(typeof v==='object')return Object.values(v).filter(x=>typeof x==='string'||typeof x==='number').join(' ')}catch{}return value}
async function load(){loading.value=true;error.value="";try{const data=await baseStocktakingApi.supplier(baseId.value,supplierId.value,date.value);supplier.value=data.supplier;items.value=data.items}catch(e){error.value=e instanceof Error?e.message:"盘点详情加载失败"}finally{loading.value=false;uni.stopPullDownRefresh()}}
onLoad(q=>{baseId.value=Number(q?.baseId);supplierId.value=Number(q?.supplierId);date.value=String(q?.date||'');load()});onPullDownRefresh(load);
</script>
<template><view class="page"><view v-if="supplier" class="supplier"><b>{{supplier.name}}</b><WarePhoneLink :phone="supplier.phone" /></view><view class="head"><text>花材</text><text>总数</text><text>已盘点</text></view><WareState v-if="loading" type="loading" title="正在加载盘点详情"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!items.length" type="empty" title="暂无盘点数据"/><view v-else v-for="item in items" :key="`${item.productId}-${item.rank}-${item.specification}`" class="row"><view><b>{{item.name}} <i>{{['','A级','B级','C级','D级','E级'][item.rank]||''}}</i></b><small v-if="specification(item.specification)">{{specification(item.specification)}}</small></view><strong>{{item.totalNum}}</strong><strong>{{item.inventoryNum}}</strong></view></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx 20rpx 40rpx;background:var(--wms-background)}.supplier{padding:10rpx 10rpx 18rpx}.supplier b{display:block;font-size:23rpx}.head,.row{display:grid;grid-template-columns:minmax(0,2fr) 1fr 1fr;align-items:center}.head{padding:11rpx 18rpx;background:var(--wms-primary-700);color:#fff;font-size:19rpx;font-weight:700}.row{min-height:76rpx;margin-top:8rpx;padding:10rpx 18rpx;background:#fff}.row b{font-size:19rpx}.row b i{color:var(--wms-success);font-style:normal;font-weight:500}.row small{display:table;margin-top:5rpx;padding:1rpx 7rpx;border-radius:4rpx;background:var(--wms-success);color:#fff;font-size:15rpx}.row strong{font-size:20rpx}</style>
<style scoped>.supplier b{font-size:var(--wms-font-list-title)}.head{font-size:var(--wms-font-list-meta)}.row{font-size:var(--wms-font-list-body);line-height:var(--wms-line-list)}.row b{font-size:var(--wms-font-list-body);font-weight:650}.row small{font-size:18rpx;font-weight:650}.row strong{font-size:var(--wms-font-list-body);font-weight:700}</style>
